export default function FeedPage() {
  const [activeTab, setActiveTab] = React.useState<TabId>("all");

  const filteredSignals = React.useMemo(() => {
    if (activeTab === "all" || activeTab === "news") return AI_SIGNALS;
    if (activeTab === "crypto") {
      return AI_SIGNALS.filter((s) => s.category === "crypto");
    }
    if (activeTab === "stocks") {
      return AI_SIGNALS.filter((s) => s.category === "stock");
    }
    return AI_SIGNALS;
  }, [activeTab]);

  return (
    <main className="min-h-screen w-full bg-slate-950 text-slate-50">
      <div className="mx-auto flex max-w-md flex-col gap-8 px-4 pb-24 pt-6 sm:max-w-lg">
        {/* Header */}
        <header className="flex items-center justify-between">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-slate-400">
              AI Market Pulse
            </p>
            <h1 className="mt-1 text-3xl font-semibold tracking-tight">
              Tredia Feed
            </h1>
            <p className="mt-1 text-sm text-slate-400">
              Your AI mentor scanning the markets 24/7.
            </p>
          </div>
          <LivePill />
        </header>

        {/* AI Market Pulse hero */}
        <section className="rounded-3xl bg-gradient-to-b from-slate-900/90 to-slate-950/95 p-5 shadow-[0_20px_60px_rgba(0,0,0,0.65)]">
          <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-slate-400">
            AI Market Pulse
          </p>
          <h2 className="mt-2 text-base font-semibold leading-relaxed text-slate-100">
            Today&apos;s market is{" "}
            <span className="text-cyan-400">cautiously bullish</span> with
            strong momentum in{" "}
            <span className="text-cyan-400">BTC, ETH and tech stocks.</span>
          </h2>
          <p className="mt-2 text-xs text-slate-400">
            High-impact news detected in US tech and macro. Tredia is tracking
            volatility so you don&apos;t have to.
          </p>

          <div className="mt-4 grid grid-cols-3 gap-3 text-xs">
            <div>
              <p className="text-slate-400">Focus</p>
              <p className="mt-1 font-medium text-slate-100">
                BTC, ETH, NVDA
              </p>
            </div>
            <div>
              <p className="text-slate-400">Risk level</p>
              <p className="mt-1 font-medium text-amber-400">Elevated</p>
            </div>
            <div>
              <p className="text-slate-400">Next update</p>
              <p className="mt-1 font-medium text-slate-100">~5 min</p>
            </div>
          </div>

          <Button
            className="mt-5 h-10 w-full rounded-2xl bg-cyan-500 text-sm font-semibold text-slate-950 hover:bg-cyan-400"
            variant="default"
          >
            View all AI insights
          </Button>
        </section>

        {/* Tabs */}
        <section className="flex flex-col gap-4">
          <div className="flex gap-8 overflow-x-auto pb-1">
            {TABS.map((tab) => {
              const isActive = activeTab === tab.id;
              return (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => setActiveTab(tab.id)}
                  className={[
                    "whitespace-nowrap rounded-full border px-4 py-2 text-sm font-medium transition",
                    isActive
                      ? "border-transparent bg-cyan-500 text-slate-950 shadow-[0_0_0_1px_rgba(15,23,42,0.8)]"
                      : "border-slate-700 bg-slate-900 text-slate-300 hover:border-slate-500",
                  ].join(" ")}
                >
                  {tab.label}
                </button>
              );
            })}
          </div>

          {/* AI Signals */}
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold uppercase tracking-[0.16em] text-slate-400">
                AI Signals
              </p>
              <p className="text-xs text-slate-500">
                Short-term directional ideas
              </p>
            </div>
            <button className="text-xs font-semibold text-cyan-400">
              View all
            </button>
          </div>

          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            {filteredSignals.map((signal) => (
              <SignalCard key={signal.id} signal={signal} />
            ))}
          </div>
        </section>

        {/* Spotlight movers */}
        <section className="flex flex-col gap-3">
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.16em] text-slate-400">
              Spotlight movers
            </p>
            <p className="text-xs text-slate-500">
              Biggest moves your AI is watching
            </p>
          </div>

          <div className="flex flex-col gap-3">
            {SPOTLIGHT_MOVERS.map((item) => (
              <SpotlightCard key={item.id} item={item} />
            ))}
          </div>
        </section>

        {/* Live activity */}
        <section className="mb-8 flex flex-col gap-3">
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.16em] text-slate-400">
              Live activity
            </p>
            <p className="text-xs text-slate-500">
              Recent moves from top accounts
            </p>
          </div>

          <div className="flex flex-col gap-3">
            {LIVE_ACTIVITY.map((item) => (
              <ActivityRow key={item.id} item={item} />
            ))}
          </div>
        </section>
      </div>
    </main>
  );
}

function LivePill() {
  return (
    <div className="flex items-center gap-2 rounded-full border border-cyan-500/60 bg-slate-950/60 px-3 py-1 text-xs font-semibold text-cyan-400 shadow-[0_0_0_1px_rgba(8,47,73,0.4)]">
      <span className="relative flex h-2 w-2">
        <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-cyan-400/60 opacity-75" />
        <span className="relative inline-flex h-2 w-2 rounded-full bg-cyan-400" />
      </span>
      LIVE
    </div>
  );
}

function SignalCard({ signal }: { signal: AiSignal }) {
  const isBullish = signal.direction === "Bullish";
  const isBearish = signal.direction === "Bearish";

  return (
    <div className="flex h-full flex-col justify-between rounded-3xl bg-slate-900/80 p-4 shadow-[0_16px_40px_rgba(0,0,0,0.6)]">
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className="text-[11px] font-semibold text-slate-400">
            {signal.symbol}
          </p>
          <p className="text-sm font-medium text-slate-100">{signal.name}</p>
        </div>
        <span
          className={[
            "rounded-full border px-2 py-0.5 text-[11px] font-semibold",
            isBullish
              ? "border-emerald-400/60 text-emerald-400"
              : isBearish
              ? "border-rose-400/60 text-rose-400"
              : "border-slate-500 text-slate-300",
          ].join(" ")}
        >
          {signal.direction}
        </span>
      </div>

      <div className="mt-4 flex items-baseline justify-between">
        <p className="text-lg font-semibold text-slate-100">{signal.move}</p>
        <p className="text-xs text-slate-400">{signal.horizon}</p>
      </div>

      <div className="mt-3 space-y-1">
        <div className="flex items-center justify-between text-[11px]">
          <span className="text-slate-400">Confidence</span>
          <span className="font-medium text-slate-100">
            {signal.confidence}%
          </span>
        </div>
        <div className="h-1.5 w-full rounded-full bg-slate-800">
          <div
            className="h-1.5 rounded-full bg-cyan-400"
            style={{ width: `${signal.confidence}%` }}
          />
        </div>
      </div>
    </div>
  );
}

function SpotlightCard({ item }: { item: SpotlightMove }) {
  const isBullish = item.bias === "Bullish";
  return (
    <div className="flex items-center justify-between rounded-3xl bg-slate-900/80 px-4 py-3 shadow-[0_14px_36px_rgba(0,0,0,0.55)]">
      <div>
        <p className="text-[11px] font-semibold text-slate-400">
          {item.symbol}
        </p>
        <p className="text-sm font-medium text-slate-100">{item.name}</p>
        <p className="mt-1 text-[11px] text-slate-500">{item.timeframe}</p>
      </div>
      <div className="text-right">
        <p
          className={[
            "text-sm font-semibold",
            isBullish ? "text-emerald-400" : "text-rose-400",
          ].join(" ")}
        >
          {item.change}
        </p>
        <span className="mt-1 inline-flex items-center justify-center rounded-full border border-slate-700 px-2 py-0.5 text-[11px] font-semibold text-slate-100">
          {item.bias}
        </span>
      </div>
    </div>
  );
}

function ActivityRow({ item }: { item: ActivityItem }) {
  return (
    <div className="flex items-center justify-between rounded-3xl bg-slate-900/80 px-4 py-3 shadow-[0_14px_36px_rgba(0,0,0,0.55)]">
      <div className="flex items-center gap-3">
        <div className="flex h-9 w-9 items-center justify-center rounded-full bg-slate-800 text-sm font-semibold text-slate-100">
          {item.name.charAt(0)}
        </div>
        <div>
          <p className="text-sm font-medium text-slate-100">{item.name}</p>
          <p className="text-[11px] text-slate-400">{item.handle}</p>
          <p className="mt-1 text-[11px] text-slate-400">
            {item.description}
          </p>
        </div>
      </div>
      <div className="text-right">
        <p className="text-[11px] text-slate-500">{item.timeAgo}</p>
        <p className="mt-1 text-sm font-semibold text-emerald-400">
          {item.change}
        </p>
      </div>
    </div>
  );
}
